<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Registro de alumnos</title>
<style>body{font-family:Arial,sans-serif;background:#f1f5f9;margin:0;padding:28px;color:#1e293b}.wrap{max-width:1200px;margin:auto;background:white;padding:24px;border-radius:10px;box-shadow:0 3px 12px #00000012}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}a,.btn{background:#2563eb;color:white;padding:9px 13px;border-radius:5px;text-decoration:none;border:0;cursor:pointer}.logout{background:#475569}.notice{padding:10px;background:#dcfce7;color:#166534}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:10px;border-bottom:1px solid #e2e8f0;text-align:left;white-space:nowrap}th{background:#f8fafc}form.inline{display:inline}.delete{background:#dc2626}.edit{background:#d97706}</style></head><body><main class="wrap">
<div class="top"><div><h1>Registro de alumnos</h1><p>Sesión: <strong><?= esc(session()->get('usuario')) ?></strong></p></div><div><a href="<?= site_url('alumnos/nuevo') ?>">Registrar alumno</a> <a class="logout" href="<?= site_url('dashboard') ?>">Panel</a>
<form class="inline" action="<?= site_url('logout') ?>" method="post"><?= csrf_field() ?><button class="btn logout" type="submit">Cerrar sesión</button></form></div></div>
<?php if ($mensaje = session()->getFlashdata('mensaje')): ?><p class="notice"><?= esc($mensaje) ?></p><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>DNI</th><th>Nombres</th><th>Apellido paterno</th><th>Apellido materno</th><th>Correo</th><th>Semestre</th><th>Fecha de registro</th><th>Acciones</th></tr></thead><tbody>
<?php if (empty($alumnos)): ?><tr><td colspan="9">Todavía no hay alumnos registrados.</td></tr><?php else: foreach ($alumnos as $alumno): ?><tr><td><?= esc($alumno['id']) ?></td><td><?= esc($alumno['dni']) ?></td><td><?= esc($alumno['nombres']) ?></td><td><?= esc($alumno['apellido_paterno']) ?></td><td><?= esc($alumno['apellido_materno']) ?></td><td><?= esc($alumno['correo']) ?></td><td><?= esc($alumno['semestre']) ?></td><td><?= esc($alumno['fecha_registro']) ?></td><td><a class="edit" href="<?= site_url('alumnos/editar/' . $alumno['id']) ?>">Editar</a> <form class="inline" action="<?= site_url('alumnos/eliminar/' . $alumno['id']) ?>" method="post" onsubmit="return confirm('¿Eliminar este registro?')"><?= csrf_field() ?><button class="btn delete" type="submit">Eliminar</button></form></td></tr><?php endforeach; endif; ?>
</tbody></table></div></main></body></html>
